mapper.select:
SELECT 
FROM TBL_TREASURY_BANK_CONNECT_CONFIGS
WHERE 1=1

    AND CONFIGNAME LIKE CONCAT('%', #{params.configName}, '%')


    AND BANKCODE = #{params.bankCode}


    AND INTERFACETYPE = #{params.interfaceType}


    AND AUTHTYPE = #{params.authType}


    AND ISENABLED = #{params.isEnabled}


    AND ORGID = #{params.orgId}

ORDER BY CREATETIME DESC

mapper.delete:
DELETE FROM TBL_TREASURY_BANK_CONNECT_CONFIGS
WHERE CONFIGID IN

    #{configId}

mapper.update:
UPDATE TBL_TREASURY_BANK_CONNECT_CONFIGS
SET ISENABLED = #{params.isEnabled},
    UPDATETIME = #{params.updateTime},
    UPDATEUSER = #{params.updateUser}
WHERE CONFIGID = #{params.configId}

mapper.select:
SELECT COUNT(*)
FROM TBL_TREASURY_BANK_CONNECT_CONFIGS
WHERE ISENABLED = #{isEnabled}

SELECT FROM TBL_TREASURY_BANK_CONNECT_CONFIGS WHERE ISENABLED = 1
AND ORGID = #{orgId}
ORDER BY CONFIGNAME

SELECT COUNT(*)
FROM TBL_TREASURY_BANK_CONNECT_CONFIGS
WHERE CONFIGNAME = #{configName} AND ORGID = #{orgId}

    AND CONFIGID != #{configId}

SELECT FROM TBL_TREASURY_BANK_CONNECT_CONFIGS WHERE INTERFACETYPE = 'BALANCE_QUERY' AND ISENABLED = 1
AND ORGID = #{orgId}
ORDER BY CONFIGNAME

SELECT FROM TBL_TREASURY_BANK_CONNECT_CONFIGS WHERE INTERFACETYPE = 'TRANSACTION_QUERY' AND ISENABLED = 1
AND ORGID = #{orgId}
ORDER BY CONFIGNAME

SELECT FROM TBL_TREASURY_BANK_CONNECT_CONFIGS WHERE INTERFACETYPE = 'PAYMENT' AND ISENABLED = 1
AND ORGID = #{orgId}
ORDER BY CONFIGNAME

SELECT FROM TBL_TREASURY_BANK_CONNECT_CONFIGS WHERE INTERFACETYPE = 'RECEIPT_DOWNLOAD' AND ISENABLED = 1
AND ORGID = #{orgId}
ORDER BY CONFIGNAME
